// generated by timing.js: do not edit
(function () { const TL = {"DURATION":437.75,"lines":[{"at":1.2,"dur":1.89,"text":"A spider drops onto your hand.","who":"narrator","scene":"spider"},{"at":3.35,"dur":1.06,"text":"You don't scream.","who":"narrator","scene":"spider"},{"at":4.67,"dur":0.85,"text":"You just...","who":"narrator","scene":"spider"},{"at":6.07,"dur":0.92,"text":"let it walk.","who":"narrator","scene":"spider"},{"at":7.25,"dur":0.71,"text":"Scared?","who":"narrator","scene":"spider"},{"at":8.38,"dur":1.14,"text":"Not even a little.","who":"narrator","scene":"spider"},{"at":10.68,"dur":2.01,"text":"The lights die in the haunted house.","who":"narrator","scene":"haunted"},{"at":12.95,"dur":1.81,"text":"A monster leaps from the dark.","who":"narrator","scene":"haunted"},{"at":15.02,"dur":1.18,"text":"Everyone shrieks.","who":"narrator","scene":"haunted"},{"at":16.46,"dur":1.5,"text":"You tap him on the shoulder.","who":"narrator","scene":"haunted"},{"at":18.42,"dur":1.36,"text":"Excuse me. Where's the exit?","who":"sam","scene":"haunted"},{"at":21.1,"dur":3.29,"text":"Your roller coaster creeps to the top of the first drop.","who":"narrator","scene":"coaster"},{"at":24.65,"dur":1.57,"text":"The whole car is screaming.","who":"narrator","scene":"coaster"},{"at":26.48,"dur":0.55,"text":"You?","who":"narrator","scene":"coaster"},{"at":27.45,"dur":0.79,"text":"You yawn.","who":"narrator","scene":"coaster"},{"at":28.5,"dur":1.24,"text":"And your popcorn...","who":"narrator","scene":"coaster"},{"at":30.29,"dur":1.16,"text":"is still in the bag.","who":"narrator","scene":"coaster"},{"at":32.61,"dur":1.21,"text":"Your name is Sam.","who":"narrator","scene":"brain"},{"at":34.08,"dur":3.7,"text":"Deep in your brain sit two tiny clusters shaped like almonds.","who":"narrator","scene":"brain"},{"at":38.04,"dur":1.93,"text":"Together they're called the amygdala.","who":"narrator","scene":"brain"},{"at":40.23,"dur":3.71,"text":"See a snake, and they fire before you even know what you saw.","who":"narrator","scene":"brain"},{"at":44.2,"dur":1.24,"text":"Your heart races.","who":"narrator","scene":"brain"},{"at":45.7,"dur":1.71,"text":"Adrenaline floods your blood.","who":"narrator","scene":"brain"},{"at":47.67,"dur":1.58,"text":"Your muscles tense to run.","who":"narrator","scene":"brain"},{"at":49.51,"dur":1.16,"text":"That's most people.","who":"narrator","scene":"brain"},{"at":50.93,"dur":0.55,"text":"You?","who":"narrator","scene":"brain"},{"at":51.9,"dur":0.73,"text":"Nothing.","who":"narrator","scene":"brain"},{"at":53.79,"dur":1.57,"text":"This isn't pure fantasy.","who":"narrator","scene":"sm"},{"at":55.62,"dur":3.33,"text":"Scientists studied a real woman known only as S.M.","who":"narrator","scene":"sm"},{"at":59.21,"dur":2.73,"text":"A rare disease damaged both her amygdalae.","who":"narrator","scene":"sm"},{"at":62.2,"dur":1.26,"text":"She handled snakes.","who":"narrator","scene":"sm"},{"at":63.72,"dur":2.35,"text":"In a haunted house, she poked a monster...","who":"narrator","scene":"sm"},{"at":66.62,"dur":1.3,"text":"and the actor jumped.","who":"narrator","scene":"sm"},{"at":69.08,"dur":1.23,"text":"But here's your rule.","who":"narrator","scene":"rule"},{"at":70.57,"dur":1.24,"text":"Your fear is gone.","who":"narrator","scene":"rule"},{"at":72.07,"dur":1.4,"text":"Your danger is not.","who":"narrator","scene":"rule"},{"at":73.73,"dur":1.64,"text":"Fear was never the enemy.","who":"narrator","scene":"rule"},{"at":75.63,"dur":1.19,"text":"It was the alarm.","who":"narrator","scene":"rule"},{"at":77.08,"dur":0.94,"text":"And yours...","who":"narrator","scene":"rule"},{"at":78.57,"dur":1.04,"text":"is unplugged.","who":"narrator","scene":"rule"},{"at":80.77,"dur":1.86,"text":"So what if you had zero fear?","who":"narrator","scene":"title"},{"at":83.05,"dur":2.11,"text":"And what's life actually like without it?","who":"narrator","scene":"title"},{"at":86.48,"dur":0.69,"text":"Monday.","who":"narrator","scene":"speech"},{"at":87.43,"dur":1.96,"text":"A speech in front of the whole school.","who":"narrator","scene":"speech"},{"at":89.65,"dur":1.39,"text":"Five hundred faces.","who":"narrator","scene":"speech"},{"at":91.3,"dur":1.46,"text":"Your voice never shakes.","who":"narrator","scene":"speech"},{"at":93.02,"dur":1.52,"text":"Mia corners you after.","who":"narrator","scene":"speech"},{"at":95,"dur":1.1,"text":"How are you not nervous?","who":"mia","scene":"speech"},{"at":96.72,"dur":2.26,"text":"Plus: exams feel like crosswords.","who":"narrator","scene":"speech"},{"at":99.24,"dur":1.28,"text":"No sweaty hands.","who":"narrator","scene":"speech"},{"at":100.78,"dur":1.19,"text":"No blank mind.","who":"narrator","scene":"speech"},{"at":103.13,"dur":1.65,"text":"Minus: personal space.","who":"narrator","scene":"space"},{"at":105.04,"dur":3.47,"text":"Most people stand roughly an arm's length from a stranger.","who":"narrator","scene":"space"},{"at":108.77,"dur":0.55,"text":"You?","who":"narrator","scene":"space"},{"at":109.74,"dur":1.04,"text":"About half that.","who":"narrator","scene":"space"},{"at":111.04,"dur":1.5,"text":"People keep stepping back.","who":"narrator","scene":"space"},{"at":112.8,"dur":1.39,"text":"Leo tugs your sleeve.","who":"narrator","scene":"space"},{"at":114.65,"dur":2.19,"text":"Mate. You're doing it again.","who":"leo","scene":"space"},{"at":118,"dur":2.76,"text":"At the zoo, you walk straight to the reptile house.","who":"narrator","scene":"zoo"},{"at":121.02,"dur":2.11,"text":"The keeper lets you hold the python.","who":"narrator","scene":"zoo"},{"at":123.39,"dur":1.5,"text":"Then begs you to stop.","who":"narrator","scene":"zoo"},{"at":125.35,"dur":1.9,"text":"Please. Put. The python. Down.","who":"keeper","scene":"zoo"},{"at":128.41,"dur":0.76,"text":"The catch?","who":"narrator","scene":"skate"},{"at":129.59,"dur":1.49,"text":"Your body still breaks.","who":"narrator","scene":"skate"},{"at":131.34,"dur":2.39,"text":"You try the biggest ramp at the skate park.","who":"narrator","scene":"skate"},{"at":133.99,"dur":0.92,"text":"First go.","who":"narrator","scene":"skate"},{"at":135.17,"dur":1.51,"text":"No wobble in your head...","who":"narrator","scene":"skate"},{"at":137.23,"dur":1.58,"text":"but plenty in your knees.","who":"narrator","scene":"skate"},{"at":139.07,"dur":0.57,"text":"Crack.","who":"narrator","scene":"skate"},{"at":139.9,"dur":1.12,"text":"A broken wrist.","who":"narrator","scene":"skate"},{"at":141.28,"dur":2.94,"text":"A bone needs around six weeks to knit back together.","who":"narrator","scene":"skate"},{"at":144.48,"dur":1.23,"text":"Fearless or not.","who":"narrator","scene":"skate"},{"at":146.87,"dur":1.8,"text":"But where it gets really crazy...","who":"narrator","scene":"bridge"},{"at":149.22,"dur":1.28,"text":"is the glass bridge.","who":"narrator","scene":"bridge"},{"at":150.76,"dur":2.19,"text":"Hundreds of meters above a valley.","who":"narrator","scene":"bridge"},{"at":153.21,"dur":2.07,"text":"Adults crawl across on their hands.","who":"narrator","scene":"bridge"},{"at":155.54,"dur":1.96,"text":"You stroll across eating an apple.","who":"narrator","scene":"bridge"},{"at":157.76,"dur":1.05,"text":"Someone films it.","who":"narrator","scene":"bridge"},{"at":159.07,"dur":0.94,"text":"By morning...","who":"narrator","scene":"bridge"},{"at":160.56,"dur":1.2,"text":"two million views.","who":"narrator","scene":"bridge"},{"at":162.92,"dur":1.61,"text":"Then a message arrives.","who":"narrator","scene":"message"},{"at":164.79,"dur":0.98,"text":"Mr. Black.","who":"narrator","scene":"message"},{"at":166.03,"dur":2.36,"text":"He runs the biggest stunt channel online.","who":"narrator","scene":"message"},{"at":168.85,"dur":0.88,"text":"We pay. Big.","who":"black","scene":"message"},{"at":169.99,"dur":1.63,"text":"Why waste a gift like yours?","who":"black","scene":"message"},{"at":172.94,"dur":1.13,"text":"And there's a cost.","who":"narrator","scene":"cost"},{"at":174.33,"dur":2.29,"text":"A roller coaster is fun for a reason.","who":"narrator","scene":"cost"},{"at":176.88,"dur":1.52,"text":"Your body screams danger.","who":"narrator","scene":"cost"},{"at":178.66,"dur":1.55,"text":"Your brain knows you're safe.","who":"narrator","scene":"cost"},{"at":180.47,"dur":1.48,"text":"That clash is the rush.","who":"narrator","scene":"cost"},{"at":182.21,"dur":1.26,"text":"You only get half.","who":"narrator","scene":"cost"},{"at":183.73,"dur":0.9,"text":"No thrill.","who":"narrator","scene":"cost"},{"at":184.89,"dur":0.96,"text":"No spark.","who":"narrator","scene":"cost"},{"at":186.11,"dur":0.68,"text":"Just...","who":"narrator","scene":"cost"},{"at":187.34,"dur":0.79,"text":"a ride.","who":"narrator","scene":"cost"},{"at":189.29,"dur":1.1,"text":"And the worst part?","who":"narrator","scene":"faces"},{"at":190.81,"dur":2.42,"text":"The amygdala doesn't only make fear.","who":"narrator","scene":"faces"},{"at":193.49,"dur":2.34,"text":"It helps you spot fear in other faces.","who":"narrator","scene":"faces"},{"at":196.09,"dur":2.04,"text":"Without it, a frightened face looks...","who":"narrator","scene":"faces"},{"at":198.68,"dur":0.66,"text":"blank.","who":"narrator","scene":"faces"},{"at":199.6,"dur":2.39,"text":"Mia trembles before her final exam.","who":"narrator","scene":"faces"},{"at":202.25,"dur":2.04,"text":"You tell her she looks totally fine.","who":"narrator","scene":"faces"},{"at":204.55,"dur":1.85,"text":"She doesn't speak to you for a week.","who":"narrator","scene":"faces"},{"at":206.66,"dur":1.51,"text":"How do you comfort someone...","who":"narrator","scene":"faces"},{"at":208.72,"dur":1.5,"text":"when you can't see them hurting?","who":"narrator","scene":"faces"},{"at":210.64,"dur":1.67,"text":"So you make yourself a rule.","who":"narrator","scene":"faces"},{"at":212.77,"dur":1.79,"text":"I can't feel it. So I have to think it.","who":"sam","scene":"faces"},{"at":215.72,"dur":1.1,"text":"Then there's Leo.","who":"narrator","scene":"leo"},{"at":217.08,"dur":1.85,"text":"Your best friend since you were six.","who":"narrator","scene":"leo"},{"at":219.19,"dur":1.73,"text":"Leo is scared of everything.","who":"narrator","scene":"leo"},{"at":221.18,"dur":0.74,"text":"Dogs.","who":"narrator","scene":"leo"},{"at":222.18,"dur":0.68,"text":"Thunder.","who":"narrator","scene":"leo"},{"at":223.12,"dur":0.79,"text":"The dark.","who":"narrator","scene":"leo"},{"at":224.17,"dur":1.18,"text":"Above all, heights.","who":"narrator","scene":"leo"},{"at":225.61,"dur":2.51,"text":"He won't stand on a chair to change a light bulb.","who":"narrator","scene":"leo"},{"at":228.38,"dur":1.78,"text":"Years ago, he made you a deal.","who":"narrator","scene":"leo"},{"at":230.62,"dur":3.02,"text":"Two taps on my chest means I'm scared.","who":"leo","scene":"leo"},{"at":233.9,"dur":1.02,"text":"Don't laugh.","who":"leo","scene":"leo"},{"at":235.38,"dur":0.96,"text":"You promised.","who":"narrator","scene":"leo"},{"at":236.6,"dur":0.86,"text":"Two taps...","who":"narrator","scene":"leo"},{"at":238.01,"dur":0.96,"text":"and you stop.","who":"narrator","scene":"leo"},{"at":240.13,"dur":3.09,"text":"When you tell him about Mr. Black, he goes quiet.","who":"narrator","scene":"tell"},{"at":243.48,"dur":1.89,"text":"You can't read his face, of course.","who":"narrator","scene":"tell"},{"at":245.63,"dur":0.92,"text":"But he taps.","who":"narrator","scene":"tell"},{"at":246.81,"dur":0.64,"text":"Twice.","who":"narrator","scene":"tell"},{"at":247.91,"dur":1.86,"text":"Sam. Please don't.","who":"leo","scene":"tell"},{"at":250.93,"dur":1.1,"text":"You go anyway.","who":"narrator","scene":"crane"},{"at":252.29,"dur":1.65,"text":"An old crane at the docks.","who":"narrator","scene":"crane"},{"at":254.2,"dur":1.89,"text":"A steel beam, forty meters up.","who":"narrator","scene":"crane"},{"at":256.35,"dur":1.66,"text":"Thirty centimeters wide.","who":"narrator","scene":"crane"},{"at":258.27,"dur":1.13,"text":"Cameras everywhere.","who":"narrator","scene":"crane"},{"at":259.66,"dur":2.84,"text":"Mr. Black clips a safety line to your belt.","who":"narrator","scene":"crane"},{"at":262.76,"dur":1.44,"text":"The stream goes live.","who":"narrator","scene":"crane"},{"at":264.46,"dur":1.25,"text":"Then you feel a tug.","who":"narrator","scene":"crane"},{"at":265.97,"dur":1.11,"text":"He's unclipped it.","who":"narrator","scene":"crane"},{"at":267.54,"dur":1.25,"text":"More real this way, kid.","who":"black","scene":"crane"},{"at":269.25,"dur":1.43,"text":"You're already halfway out.","who":"narrator","scene":"crane"},{"at":271.84,"dur":1.42,"text":"Then the ladder rattles.","who":"narrator","scene":"ladder"},{"at":273.52,"dur":0.64,"text":"Leo?","who":"narrator","scene":"ladder"},{"at":274.58,"dur":1.07,"text":"He followed you.","who":"narrator","scene":"ladder"},{"at":275.91,"dur":0.98,"text":"He's climbing.","who":"narrator","scene":"ladder"},{"at":277.35,"dur":1.7,"text":"Sam? Come back!","who":"leo","scene":"ladder"},{"at":279.51,"dur":0.92,"text":"Ten meters.","who":"narrator","scene":"ladder"},{"at":280.69,"dur":0.69,"text":"Twenty.","who":"narrator","scene":"ladder"},{"at":281.64,"dur":0.68,"text":"Thirty.","who":"narrator","scene":"ladder"},{"at":282.58,"dur":1.04,"text":"Then he stops.","who":"narrator","scene":"ladder"},{"at":283.88,"dur":0.8,"text":"Frozen.","who":"narrator","scene":"ladder"},{"at":284.94,"dur":3.27,"text":"The wind up here is far stronger than on the ground.","who":"narrator","scene":"ladder"},{"at":288.47,"dur":3.08,"text":"A fall from forty meters takes under three seconds.","who":"narrator","scene":"ladder"},{"at":291.81,"dur":1.37,"text":"And Leo's fingers...","who":"narrator","scene":"ladder"},{"at":293.73,"dur":0.91,"text":"are slipping.","who":"narrator","scene":"ladder"},{"at":295.8,"dur":1.17,"text":"You look at his face.","who":"narrator","scene":"choice"},{"at":297.23,"dur":1.04,"text":"You can't read it.","who":"narrator","scene":"choice"},{"at":298.53,"dur":1.27,"text":"To you, it's just...","who":"narrator","scene":"choice"},{"at":300.35,"dur":0.77,"text":"a face.","who":"narrator","scene":"choice"},{"at":301.38,"dur":2.33,"text":"Mr. Black hisses through your earpiece.","who":"narrator","scene":"choice"},{"at":304.17,"dur":2.86,"text":"What are you waiting for? A million people are watching.","who":"black","scene":"choice"},{"at":307.49,"dur":1.53,"text":"Ahead, the end of the beam.","who":"narrator","scene":"choice"},{"at":309.28,"dur":0.84,"text":"The views.","who":"narrator","scene":"choice"},{"at":310.38,"dur":0.72,"text":"The money.","who":"narrator","scene":"choice"},{"at":311.36,"dur":1.63,"text":"Behind you, your best friend.","who":"narrator","scene":"choice"},{"at":313.25,"dur":0.9,"text":"The views...","who":"narrator","scene":"choice"},{"at":314.7,"dur":0.83,"text":"or Leo.","who":"narrator","scene":"choice"},{"at":315.79,"dur":2.11,"text":"Then Leo lifts one shaking hand.","who":"narrator","scene":"choice"},{"at":318.16,"dur":1.21,"text":"And taps his chest.","who":"narrator","scene":"choice"},{"at":319.63,"dur":0.64,"text":"Twice.","who":"narrator","scene":"choice"},{"at":321.43,"dur":1.08,"text":"You turn around.","who":"narrator","scene":"rescue"},{"at":322.77,"dur":0.9,"text":"You don't rush.","who":"narrator","scene":"rescue"},{"at":323.93,"dur":1.08,"text":"You can't feel it...","who":"narrator","scene":"rescue"},{"at":325.56,"dur":1.04,"text":"so you think it.","who":"narrator","scene":"rescue"},{"at":326.86,"dur":1.3,"text":"Step. Breathe. Step.","who":"narrator","scene":"rescue"},{"at":328.42,"dur":1.54,"text":"You crouch beside the ladder.","who":"narrator","scene":"rescue"},{"at":330.42,"dur":1.5,"text":"Leo. Look at me. Can you hear me?","who":"sam","scene":"rescue"},{"at":332.34,"dur":1.28,"text":"Three points of contact.","who":"sam","scene":"rescue"},{"at":333.88,"dur":2.24,"text":"Two hands and a foot. Or two feet and a hand.","who":"sam","scene":"rescue"},{"at":336.38,"dur":0.83,"text":"Always three.","who":"sam","scene":"rescue"},{"at":337.67,"dur":1.94,"text":"It's the oldest rule in climbing.","who":"narrator","scene":"rescue"},{"at":339.87,"dur":1.21,"text":"You talk him down.","who":"narrator","scene":"rescue"},{"at":341.34,"dur":1.28,"text":"One rung at a time.","who":"narrator","scene":"rescue"},{"at":342.88,"dur":1.74,"text":"Your calm becomes his calm.","who":"narrator","scene":"rescue"},{"at":344.88,"dur":2.07,"text":"The only steady thing in the sky...","who":"narrator","scene":"rescue"},{"at":347.5,"dur":0.98,"text":"is your voice.","who":"narrator","scene":"rescue"},{"at":349.64,"dur":2.29,"text":"At the bottom, he collapses in the dust.","who":"narrator","scene":"truth"},{"at":352.19,"dur":2.83,"text":"Then you pick up the camera Mr. Black dropped.","who":"narrator","scene":"truth"},{"at":355.28,"dur":0.88,"text":"Still live.","who":"narrator","scene":"truth"},{"at":356.42,"dur":2.11,"text":"You point it at the loose safety line.","who":"narrator","scene":"truth"},{"at":358.99,"dur":1.49,"text":"He unclipped this. On purpose.","who":"sam","scene":"truth"},{"at":360.94,"dur":0.94,"text":"You don't shout.","who":"narrator","scene":"truth"},{"at":362.14,"dur":1.06,"text":"You don't shove him.","who":"narrator","scene":"truth"},{"at":363.46,"dur":1.33,"text":"You just tell the truth.","who":"narrator","scene":"truth"},{"at":365.05,"dur":1.95,"text":"By evening, his channel is gone.","who":"narrator","scene":"truth"},{"at":368.16,"dur":0.82,"text":"And remember:","who":"narrator","scene":"lesson"},{"at":369.24,"dur":2.29,"text":"no video is worth a hospital bed.","who":"narrator","scene":"lesson"},{"at":371.79,"dur":3.32,"text":"If someone asks you to drop your safety gear for views...","who":"narrator","scene":"lesson"},{"at":375.66,"dur":1.65,"text":"they're not the one who'd fall.","who":"narrator","scene":"lesson"},{"at":378.47,"dur":1.78,"text":"The comments fill with one name.","who":"narrator","scene":"brave"},{"at":380.51,"dur":0.66,"text":"Leo.","who":"narrator","scene":"brave"},{"at":381.43,"dur":2.82,"text":"Leo, who climbed thirty meters while terrified.","who":"narrator","scene":"brave"},{"at":384.51,"dur":1.22,"text":"Because that's brave.","who":"narrator","scene":"brave"},{"at":385.99,"dur":1.33,"text":"Not feeling nothing...","who":"narrator","scene":"brave"},{"at":387.87,"dur":2.4,"text":"feeling everything, and climbing anyway.","who":"narrator","scene":"brave"},{"at":391.43,"dur":2.21,"text":"Later he asks how you stayed so calm.","who":"narrator","scene":"end"},{"at":393.9,"dur":0.84,"text":"You shrug.","who":"narrator","scene":"end"},{"at":395.2,"dur":1.79,"text":"I can't feel it. So I have to think it.","who":"sam","scene":"end"},{"at":397.45,"dur":0.88,"text":"He grins.","who":"narrator","scene":"end"},{"at":398.79,"dur":2.42,"text":"Then I'll feel it for both of us.","who":"leo","scene":"end"},{"at":401.67,"dur":2.2,"text":"You still can't see the fear on his face.","who":"narrator","scene":"end"},{"at":404.13,"dur":1.47,"text":"But you can see that grin.","who":"narrator","scene":"end"},{"at":405.86,"dur":4.05,"text":"And when he hugs you, your heart does something it hasn't done in years.","who":"narrator","scene":"end"},{"at":410.17,"dur":0.81,"text":"It jumps.","who":"narrator","scene":"end"},{"at":412.14,"dur":2.71,"text":"That night, an envelope slides under your door.","who":"narrator","scene":"sting"},{"at":415.11,"dur":0.93,"text":"No stamp.","who":"narrator","scene":"sting"},{"at":416.3,"dur":0.79,"text":"No name.","who":"narrator","scene":"sting"},{"at":417.35,"dur":0.83,"text":"One line.","who":"narrator","scene":"sting"},{"at":418.44,"dur":2.46,"text":"We know what you can't feel. We need you.","who":"narrator","scene":"sting"},{"at":422.06,"dur":1.9,"text":"So what would you do with zero fear?","who":"narrator","scene":"cta"},{"at":424.38,"dur":2.96,"text":"Tell us the first scary thing you'd try in the comments.","who":"narrator","scene":"cta"},{"at":427.6,"dur":2.55,"text":"And if you got chills when Leo tapped twice...","who":"narrator","scene":"cta"},{"at":430.7,"dur":2.29,"text":"hit like, and subscribe for Part Two.","who":"narrator","scene":"cta"}],"scenes":[{"id":"spider","t0":0,"t1":10.23},{"id":"haunted","t0":10.23,"t1":20.65},{"id":"coaster","t0":20.65,"t1":32.16},{"id":"brain","t0":32.16,"t1":53.34},{"id":"sm","t0":53.34,"t1":68.63},{"id":"rule","t0":68.63,"t1":80.32},{"id":"title","t0":80.32,"t1":86.03},{"id":"speech","t0":86.03,"t1":102.68},{"id":"space","t0":102.68,"t1":117.55},{"id":"zoo","t0":117.55,"t1":127.96},{"id":"skate","t0":127.96,"t1":146.42},{"id":"bridge","t0":146.42,"t1":162.47},{"id":"message","t0":162.47,"t1":172.49},{"id":"cost","t0":172.49,"t1":188.84},{"id":"faces","t0":188.84,"t1":215.27},{"id":"leo","t0":215.27,"t1":239.68},{"id":"tell","t0":239.68,"t1":250.48},{"id":"crane","t0":250.48,"t1":271.39},{"id":"ladder","t0":271.39,"t1":295.35},{"id":"choice","t0":295.35,"t1":320.98},{"id":"rescue","t0":320.98,"t1":349.19},{"id":"truth","t0":349.19,"t1":367.71},{"id":"lesson","t0":367.71,"t1":378.02},{"id":"brave","t0":378.02,"t1":390.98},{"id":"end","t0":390.98,"t1":411.69},{"id":"sting","t0":411.69,"t1":421.61},{"id":"cta","t0":421.61,"t1":437.75}]};
if (typeof module !== 'undefined') module.exports = TL; else globalThis.TIMELINE = TL; })();
